import { Switch, Route } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { useAuth } from "@/hooks/useAuth";
import { AgeGate, useAgeVerification } from "@/components/age-gate";
import NotFound from "@/pages/not-found";
import Landing from "@/pages/landing";
import Home from "@/pages/home";
import Assessment from "@/pages/assessment";
import Dashboard from "@/pages/dashboard";
import TreatmentPlan from "@/pages/treatment-plan";
import Admin from "@/pages/admin";
import Subscribe from "@/pages/subscribe";
import Billing from "@/pages/billing";
import AuthPage from "@/pages/auth";
import Support from "@/pages/support";

function Router() {
  const { isAuthenticated, isLoading } = useAuth();
  const { isVerified, setVerified } = useAgeVerification();

  if (isLoading || isVerified === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!isVerified) {
    return <AgeGate onConfirm={setVerified} />;
  }

  return (
    <Switch>
      <Route path="/">
        {isAuthenticated ? <Home /> : <Landing />}
      </Route>
      <Route path="/login" component={AuthPage} />
      <Route path="/register" component={AuthPage} />
      <Route path="/auth" component={AuthPage} />
      <Route path="/assessment">
        {isAuthenticated ? <Assessment /> : <AuthPage />}
      </Route>
      <Route path="/dashboard">
        {isAuthenticated ? <Dashboard /> : <AuthPage />}
      </Route>
      <Route path="/treatment-plan/:id">
        {isAuthenticated ? <TreatmentPlan /> : <AuthPage />}
      </Route>
      <Route path="/admin">
        {isAuthenticated ? <Admin /> : <AuthPage />}
      </Route>
      <Route path="/billing">
        {isAuthenticated ? <Billing /> : <AuthPage />}
      </Route>
      <Route path="/subscribe">
        {isAuthenticated ? <Subscribe /> : <AuthPage />}
      </Route>
      <Route path="/support">
        {isAuthenticated ? <Support /> : <AuthPage />}
      </Route>
      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Toaster />
        <Router />
      </TooltipProvider>
    </QueryClientProvider>
  );
}

export default App;

