                                <EyeOff className="h-4 w-4 text-muted-foreground" />
                              ) : (
                                <Eye className="h-4 w-4 text-muted-foreground" />
                              )}
                            </Button>
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <Button 
                    type="submit" 
                    className="w-full" 
                    disabled={registerMutation.isPending}
                    data-testid="button-register"
                  >
                    {registerMutation.isPending ? "Creating account..." : "Create account"}
                  </Button>
                </form>
              </Form>
            )}

            {/* Divider */}
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <Separator className="w-full" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="bg-background px-3 text-muted-foreground">
                  {isLogin ? "Or sign in with" : "Or sign up with"}
                </span>
              </div>
            </div>

            {/* OAuth Buttons */}
            <div className="space-y-2">
              <Button
                variant="outline"
                onClick={() => window.location.href = "/api/login"}
                className="w-full h-11 justify-start"
                data-testid="button-replit-auth"
              >
                <svg className="w-5 h-5 mr-3" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M7.083 10.5c0-.414.336-.75.75-.75h6.334c.414 0 .75.336.75.75s-.336.75-.75.75H7.833c-.414 0-.75-.336-.75-.75z"/>
                  <path fillRule="evenodd" d="M3.25 12c0-4.832 3.918-8.75 8.75-8.75s8.75 3.918 8.75 8.75-3.918 8.75-8.75 8.75S3.25 16.832 3.25 12zM12 4.75c-4.004 0-7.25 3.246-7.25 7.25s3.246 7.25 7.25 7.25 7.25-3.246 7.25-7.25S16.004 4.75 12 4.75z" clipRule="evenodd"/>
                </svg>
                <span className="flex-1 text-left">Replit</span>
                <span className="text-xs text-muted-foreground">{isLogin ? "Sign in with Replit" : "Sign up with Replit"}</span>
              </Button>

              <Button
                variant="outline"
                onClick={() => handleOAuthLogin("google")}
                className="w-full h-11 justify-start"
                data-testid="button-google-auth"
              >
                <FaGoogle className="w-5 h-5 mr-3 text-red-500" />
                <span className="flex-1 text-left">Google</span>
                <span className="text-xs text-muted-foreground">{isLogin ? "Sign in with Google" : "Sign up with Google"}</span>
              </Button>

              <Button
                variant="outline"
                onClick={() => handleOAuthLogin("twitter")}
                className="w-full h-11 justify-start"
                data-testid="button-twitter-auth"
              >
                <FaTwitter className="w-5 h-5 mr-3 text-blue-500" />
                <span className="flex-1 text-left">X (Twitter)</span>
                <span className="text-xs text-muted-foreground">{isLogin ? "Sign in with X" : "Sign up with X"}</span>
              </Button>
            </div>

            {/* Toggle Form Type */}
            <div className="text-center pt-2">
              <Button
                variant="link"
                onClick={() => setIsLogin(!isLogin)}
                className="text-sm"
                data-testid="button-toggle-auth-mode"
              >
                {isLogin 
                  ? "Don't have an account? Sign up" 
                  : "Already have an account? Sign in"
                }
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Footer */}
        <div className="text-center text-sm text-muted-foreground">
          <Link to="/" className="hover:underline">
            ← Back to home
          </Link>
        </div>
      </div>
    </div>
  );
}

