import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { isUnauthorizedError } from "@/lib/authUtils";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import Header from "@/components/layout/header";
import { AlertTriangle, Users, Brain, Shield, Clock, TrendingUp, Search, FileText } from "lucide-react";

export default function Admin() {
  const { toast } = useToast();
  const { user, isAuthenticated, isLoading } = useAuth();
  const [searchTerm, setSearchTerm] = useState("");

  const { data: users, isLoading: usersLoading } = useQuery({
    queryKey: ["/api/admin/users"],
    retry: false,
  });

  const { data: assessments, isLoading: assessmentsLoading } = useQuery({
    queryKey: ["/api/admin/assessments"],
    retry: false,
  });

  const { data: crisisAlerts, isLoading: alertsLoading } = useQuery({
    queryKey: ["/api/admin/crisis-alerts"],
    retry: false,
  });

  const resolveCrisisMutation = useMutation({
    mutationFn: async (alertId: string) => {
      await apiRequest("PATCH", `/api/admin/crisis-alerts/${alertId}/resolve`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/crisis-alerts"] });
      toast({
        title: "Crisis Alert Resolved",
        description: "The crisis alert has been marked as resolved.",
      });
    },
    onError: (error) => {
      if (isUnauthorizedError(error as Error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: "Failed to resolve crisis alert. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Redirect if not authenticated or not admin
  useEffect(() => {
    if (!isLoading && (!isAuthenticated || !user?.isAdmin)) {
      toast({
        title: "Access Denied",
        description: "You don't have permission to access the admin panel.",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/";
      }, 1000);
      return;
    }
  }, [isAuthenticated, isLoading, user, toast]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!isAuthenticated || !user?.isAdmin) {
    return null;
  }

  const filteredAssessments = assessments?.filter((assessment: any) =>
    assessment.type.toLowerCase().includes(searchTerm.toLowerCase()) ||
    assessment.severity.toLowerCase().includes(searchTerm.toLowerCase())
  ) || [];

  const unresolvedAlerts = crisisAlerts?.filter((alert: any) => !alert.resolved) || [];
  const severeCases = assessments?.filter((assessment: any) => 
    assessment.severity === 'severe' || assessment.severity === 'moderately_severe'
  ) || [];

  const handleResolveCrisis = (alertId: string) => {
    resolveCrisisMutation.mutate(alertId);
  };

  return (
    <div className="min-h-screen bg-background" data-testid="admin-page">
      <Header />

      <main className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-foreground mb-2" data-testid="text-admin-title">
            Clinical Dashboard
          </h1>
          <p className="text-muted-foreground">
            Monitor patient assessments, review treatment progress, and manage crisis alerts for audit and compliance.
          </p>
        </div>

        {/* Key Metrics */}
        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <Card data-testid="card-total-users">
            <CardContent className="p-6">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-primary/10 rounded-lg flex items-center justify-center">
                  <Users className="h-6 w-6 text-primary" />
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Total Users</p>
                  <p className="text-2xl font-bold">{users?.length || 0}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card data-testid="card-total-assessments">
            <CardContent className="p-6">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-secondary/10 rounded-lg flex items-center justify-center">
                  <Brain className="h-6 w-6 text-secondary" />
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Total Assessments</p>
                  <p className="text-2xl font-bold">{assessments?.length || 0}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card data-testid="card-crisis-alerts">
            <CardContent className="p-6">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-destructive/10 rounded-lg flex items-center justify-center">
                  <AlertTriangle className="h-6 w-6 text-destructive" />
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Crisis Alerts</p>
                  <p className="text-2xl font-bold text-destructive">{unresolvedAlerts.length}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card data-testid="card-severe-cases">
            <CardContent className="p-6">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-yellow-100 rounded-lg flex items-center justify-center">
                  <TrendingUp className="h-6 w-6 text-yellow-600" />
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Severe Cases</p>
                  <p className="text-2xl font-bold text-yellow-600">{severeCases.length}</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        <Tabs defaultValue="alerts" className="space-y-6">
          <TabsList data-testid="tabs-admin">
            <TabsTrigger value="alerts" data-testid="tab-alerts">Crisis Alerts</TabsTrigger>
            <TabsTrigger value="assessments" data-testid="tab-assessments">Recent Assessments</TabsTrigger>
            <TabsTrigger value="users" data-testid="tab-users">User Management</TabsTrigger>
            <TabsTrigger value="audit" data-testid="tab-audit">Audit & Compliance</TabsTrigger>
          </TabsList>

          <TabsContent value="alerts" className="space-y-6">
            <Card data-testid="card-crisis-alerts-list">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <AlertTriangle className="h-5 w-5 text-destructive" />
                  <span>Crisis Alerts Requiring Immediate Attention</span>
                  {unresolvedAlerts.length > 0 && (
                    <Badge variant="destructive">{unresolvedAlerts.length}</Badge>
                  )}
                </CardTitle>
              </CardHeader>
              <CardContent>
                {alertsLoading ? (
                  <div className="space-y-3">
                    {[...Array(3)].map((_, i) => (
                      <div key={i} className="h-20 bg-muted rounded animate-pulse"></div>
                    ))}
                  </div>
                ) : unresolvedAlerts.length > 0 ? (
                  <div className="space-y-4">
                    {unresolvedAlerts.map((alert: any) => (
                      <div key={alert.id} className="border border-destructive/20 rounded-lg p-4 bg-destructive/5">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center space-x-3 mb-2">
                              <Badge variant="destructive" className="capitalize">
                                {alert.severity} Risk
                              </Badge>
                              <Badge variant="outline" className="capitalize">
                                {alert.alertType.replace('_', ' ')}
                              </Badge>
                              <span className="text-sm text-muted-foreground">
                                User ID: {alert.userId}
                              </span>
                            </div>
                            <p className="text-sm mb-2">{alert.description}</p>
                            <p className="text-xs text-muted-foreground">
                              Triggered: {new Date(alert.createdAt).toLocaleString()}
                            </p>
                          </div>
                          <Button
                            size="sm"
                            onClick={() => handleResolveCrisis(alert.id)}
                            disabled={resolveCrisisMutation.isPending}
                            data-testid={`button-resolve-${alert.id}`}
                          >
                            {resolveCrisisMutation.isPending ? "Resolving..." : "Mark Resolved"}
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <Shield className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-semibold mb-2">No Active Crisis Alerts</h3>
                    <p className="text-muted-foreground">All crisis alerts have been resolved.</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="assessments" className="space-y-6">
            <Card data-testid="card-assessment-search">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="flex items-center space-x-2">
                    <Brain className="h-5 w-5" />
                    <span>Recent Assessments Requiring Review</span>
                  </CardTitle>
                  <div className="flex items-center space-x-2">
                    <Search className="h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search assessments..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="w-64"
                      data-testid="input-search-assessments"
                    />
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                {assessmentsLoading ? (
                  <div className="space-y-3">
                    {[...Array(5)].map((_, i) => (
                      <div key={i} className="h-16 bg-muted rounded animate-pulse"></div>
                    ))}
                  </div>
                ) : filteredAssessments.length > 0 ? (
                  <div className="space-y-3">
                    {filteredAssessments.map((assessment: any) => (
                      <div key={assessment.id} className="border rounded-lg p-4 hover:bg-muted/50 transition-colors">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center space-x-4">
                            <div className={`w-3 h-3 rounded-full ${
                              assessment.severity === 'severe' || assessment.severity === 'moderately_severe'
                                ? 'bg-red-500'
                                : assessment.severity === 'moderate'
                                ? 'bg-yellow-500'
                                : 'bg-green-500'
                            }`}></div>
                            <div>
                              <p className="font-medium">
                                User #{assessment.userId.substring(0, 8)}... | {assessment.type.toUpperCase()}
                              </p>
                              <p className="text-sm text-muted-foreground">
                                Score: {assessment.score} | Severity: {assessment.severity.replace('_', ' ')}
                              </p>
                            </div>
                          </div>
                          <div className="text-right">
                            <p className="text-sm text-muted-foreground">
                              {new Date(assessment.createdAt).toLocaleString()}
                            </p>
                            <Button
                              size="sm"
                              variant="outline"
                              data-testid={`button-review-${assessment.id}`}
                            >
                              Review Details
                            </Button>
                          </div>
                        </div>
                        {assessment.aiAnalysis && (
                          <div className="mt-3 p-3 bg-muted/30 rounded text-sm">
                            <p className="font-medium mb-1">AI Analysis:</p>
                            <p className="text-muted-foreground">
                              {assessment.aiAnalysis.length > 150 
                                ? `${assessment.aiAnalysis.substring(0, 150)}...`
                                : assessment.aiAnalysis
                              }
                            </p>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <Brain className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-semibold mb-2">No Assessments Found</h3>
                    <p className="text-muted-foreground">
                      {searchTerm ? "No assessments match your search criteria." : "No assessments have been completed yet."}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="users" className="space-y-6">
            <Card data-testid="card-user-management">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <Users className="h-5 w-5" />
                  <span>User Management</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                {usersLoading ? (
                  <div className="space-y-3">
                    {[...Array(5)].map((_, i) => (
                      <div key={i} className="h-16 bg-muted rounded animate-pulse"></div>
                    ))}
                  </div>
                ) : users && users.length > 0 ? (
                  <div className="space-y-3">
                    {users.map((userData: any) => (
                      <div key={userData.id} className="border rounded-lg p-4">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center space-x-4">
                            <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center">
                              <Users className="h-5 w-5 text-primary" />
                            </div>
                            <div>
                              <p className="font-medium">
                                {userData.firstName} {userData.lastName}
                              </p>
                              <p className="text-sm text-muted-foreground">
                                {userData.email} | ID: {userData.id.substring(0, 8)}...
                              </p>
                            </div>
                          </div>
                          <div className="text-right">
                            <div className="flex items-center space-x-2 mb-1">
                              {userData.isAdmin && (
                                <Badge variant="secondary">Admin</Badge>
                              )}
                            </div>
                            <p className="text-sm text-muted-foreground">
                              Joined: {new Date(userData.createdAt).toLocaleDateString()}
                            </p>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <Users className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-semibold mb-2">No Users Found</h3>
                    <p className="text-muted-foreground">No users have registered yet.</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="audit" className="space-y-6">
            <Card data-testid="card-audit-compliance">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <FileText className="h-5 w-5" />
                  <span>Audit & Compliance Report</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-primary mb-2">
                      {assessments?.length || 0}
                    </div>
                    <div className="text-sm text-muted-foreground">Total Assessments Completed</div>
                  </div>

                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-secondary mb-2">100%</div>
                    <div className="text-sm text-muted-foreground">HIPAA Compliance Rate</div>
                  </div>

                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-accent mb-2">24/7</div>
                    <div className="text-sm text-muted-foreground">Data Backup & Security</div>
                  </div>

                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-green-600 mb-2">
                      {crisisAlerts?.filter((alert: any) => alert.resolved).length || 0}
                    </div>
                    <div className="text-sm text-muted-foreground">Crisis Alerts Resolved</div>
                  </div>

                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-yellow-600 mb-2">
                      {severeCases.length}
                    </div>
                    <div className="text-sm text-muted-foreground">High-Severity Cases</div>
                  </div>

                  <div className="text-center p-6 bg-muted/30 rounded-lg">
                    <div className="text-3xl font-bold text-primary mb-2">
                      {users?.length || 0}
                    </div>
                    <div className="text-sm text-muted-foreground">Active Users</div>
                  </div>
                </div>

                <div className="mt-8 p-6 bg-green-50 border border-green-200 rounded-lg">
                  <div className="flex items-center space-x-3 mb-4">
                    <Shield className="h-6 w-6 text-green-600" />
                    <h4 className="font-semibold text-green-800">Compliance Status</h4>
                  </div>
                  <div className="space-y-2 text-sm text-green-700">
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                      <span>HIPAA Privacy Rule compliance maintained</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                      <span>All patient data encrypted and secure</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                      <span>Crisis protocols followed for all alerts</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                      <span>Audit trail maintained for all actions</span>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
}

shared/schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  index,
  jsonb,
  pgTable,
  timestamp,
  varchar,
  text,
  integer,
  boolean,
  decimal,
  pgEnum,
} from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Session storage table for Replit Auth
export const sessions = pgTable(
  "sessions",
  {
    sid: varchar("sid").primaryKey(),
    sess: jsonb("sess").notNull(),
    expire: timestamp("expire").notNull(),
  },
  (table) => [index("IDX_session_expire").on(table.expire)],
);

// Authentication provider enum
export const authProviderEnum = pgEnum('auth_provider', [
  'replit',
  'google',
  'twitter',
  'email'
]);

// User storage table with multi-auth support
export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: varchar("email").unique(),
  passwordHash: varchar("password_hash"), // For email/password auth
  firstName: varchar("first_name"),
  lastName: varchar("last_name"),
  profileImageUrl: varchar("profile_image_url"),
  isAdmin: boolean("is_admin").default(false),
  stripeCustomerId: varchar("stripe_customer_id").unique(),
  stripeSubscriptionId: varchar("stripe_subscription_id").unique(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// User authentication providers table
export const userAuthProviders = pgTable("user_auth_providers", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  provider: authProviderEnum("provider").notNull(),
  providerId: varchar("provider_id").notNull(), // ID from the OAuth provider
  providerEmail: varchar("provider_email"), // Email from the provider
  accessToken: text("access_token"), // OAuth access token
  refreshToken: text("refresh_token"), // OAuth refresh token
  tokenExpiresAt: timestamp("token_expires_at"), // When tokens expire
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
}, (table) => [
  // Unique constraint: one provider per user
  index("unique_user_provider").on(table.userId, table.provider),
  // Unique constraint: one provider ID per provider
  index("unique_provider_id").on(table.provider, table.providerId),
]);

// Assessment types enum
export const assessmentTypeEnum = pgEnum('assessment_type', [
  'phq9',
  'gad7',
  'stress_burnout',
  'ptsd',
  'sleep_quality',
  'comprehensive',
  'conversation_ai'
]);

// Assessment severity enum
export const severityEnum = pgEnum('severity', [
  'minimal',
  'mild',
  'moderate',
  'moderately_severe',
  'severe'
]);

// Conversation assessment status enum
export const conversationStatusEnum = pgEnum('conversation_status', [
  'in_progress',
  'completed',
  'abandoned'
]);

// Conversational assessments table - stores AI-driven chat sessions
export const conversationAssessments = pgTable("conversation_assessments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  status: conversationStatusEnum("status").default('in_progress'),
  conversationTranscript: jsonb("conversation_transcript").notNull(), // Array of {role, content, timestamp, metadata}
  aiCheckpoints: jsonb("ai_checkpoints"), // Interim AI insights per turn
  summaryInsights: jsonb("summary_insights"), // Final AI analysis
  assessmentId: varchar("assessment_id").references(() => assessments.id), // Link to final assessment
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Assessments table
export const assessments = pgTable("assessments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  type: assessmentTypeEnum("type").notNull(),
  responses: jsonb("responses").notNull(), // Store assessment responses
  score: integer("score").default(0), // Made optional for AI-derived scores
  severity: severityEnum("severity").notNull(),
  aiAnalysis: text("ai_analysis"), // AI-generated analysis
  recommendations: jsonb("recommendations"), // AI recommendations
  riskFactors: jsonb("risk_factors"), // Identified risk factors
  conversationAssessmentId: varchar("conversation_assessment_id").references(() => conversationAssessments.id), // Link to conversation
  createdAt: timestamp("created_at").defaultNow(),
});

// Treatment plan status enum
export const planStatusEnum = pgEnum('plan_status', [
  'active',
  'completed',
  'paused',
  'discontinued'
]);

// Treatment plans table
export const treatmentPlans = pgTable("treatment_plans", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  assessmentId: varchar("assessment_id").notNull().references(() => assessments.id),
  title: varchar("title").notNull(),
  description: text("description"),
  status: planStatusEnum("status").default('active'),
  totalWeeks: integer("total_weeks").notNull(),
  currentWeek: integer("current_week").default(1),
  progressPercentage: decimal("progress_percentage", { precision: 5, scale: 2 }).default('0'),
  modules: jsonb("modules").notNull(), // Course-like modules structure
  goals: jsonb("goals"), // Treatment goals
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Treatment plan modules table
export const treatmentModules = pgTable("treatment_modules", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  planId: varchar("plan_id").notNull().references(() => treatmentPlans.id),
  title: varchar("title").notNull(),
  description: text("description"),
  week: integer("week").notNull(),
  order: integer("order").notNull(),
  content: jsonb("content").notNull(), // Lessons, exercises, activities
  isCompleted: boolean("is_completed").default(false),
  completedAt: timestamp("completed_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Progress tracking table
export const progressEntries = pgTable("progress_entries", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  planId: varchar("plan_id").notNull().references(() => treatmentPlans.id),
  moduleId: varchar("module_id").references(() => treatmentModules.id),
  date: timestamp("date").notNull(),
  activityType: varchar("activity_type").notNull(), // 'exercise', 'lesson', 'journal', etc.
  activityName: varchar("activity_name").notNull(),
  completed: boolean("completed").default(false),
  notes: text("notes"),
  moodRating: integer("mood_rating"), // 1-10 scale
  anxietyLevel: integer("anxiety_level"), // 1-10 scale
  createdAt: timestamp("created_at").defaultNow(),
});

// Crisis alerts table
export const crisisAlerts = pgTable("crisis_alerts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  assessmentId: varchar("assessment_id").references(() => assessments.id),
  alertType: varchar("alert_type").notNull(), // 'suicide_risk', 'self_harm', 'crisis'
  severity: varchar("severity").notNull(), // 'low', 'medium', 'high', 'critical'
  description: text("description").notNull(),
  resolved: boolean("resolved").default(false),
  resolvedBy: varchar("resolved_by").references(() => users.id),
  resolvedAt: timestamp("resolved_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Subscription plan intervals enum
export const planIntervalEnum = pgEnum('plan_interval', [
  'monthly',
  'quarterly', 
  'yearly'
]);

// Subscription plan types enum
export const planTypeEnum = pgEnum('plan_type', [
  'basic',
  'premium',
  'professional',
  'enterprise'
]);

// Subscription plans table
export const subscriptionPlans = pgTable("subscription_plans", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  description: text("description"),
  type: planTypeEnum("type").notNull(),
  interval: planIntervalEnum("interval").notNull(),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("USD"),
  stripePriceId: varchar("stripe_price_id").unique().notNull(),
  stripeProductId: varchar("stripe_product_id").notNull(),
  features: jsonb("features").notNull(), // Array of features
  assessmentsPerMonth: integer("assessments_per_month").default(-1), // -1 for unlimited
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Subscription status enum
export const subscriptionStatusEnum = pgEnum('subscription_status', [
  'active',
  'inactive',
  'past_due',
  'canceled',
  'unpaid',
  'trialing'
]);

// User subscriptions table
export const userSubscriptions = pgTable("user_subscriptions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  planId: varchar("plan_id").notNull().references(() => subscriptionPlans.id),
  stripeSubscriptionId: varchar("stripe_subscription_id").unique().notNull(),
  stripeCustomerId: varchar("stripe_customer_id").notNull(),
  status: subscriptionStatusEnum("status").notNull(),
  currentPeriodStart: timestamp("current_period_start").notNull(),
  currentPeriodEnd: timestamp("current_period_end").notNull(),
  cancelAtPeriodEnd: boolean("cancel_at_period_end").default(false),
  canceledAt: timestamp("canceled_at"),
  trialStart: timestamp("trial_start"),
  trialEnd: timestamp("trial_end"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Payment status enum
export const paymentStatusEnum = pgEnum('payment_status', [
  'pending',
  'succeeded',
  'failed',
  'canceled',
  'refunded',
  'partially_refunded'
]);

// Payment type enum
export const paymentTypeEnum = pgEnum('payment_type', [
  'subscription',
  'one_time',
  'refund'
]);

// Payments table for audit and tracking
export const payments = pgTable("payments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  subscriptionId: varchar("subscription_id").references(() => userSubscriptions.id),
  planId: varchar("plan_id").references(() => subscriptionPlans.id),
  stripePaymentIntentId: varchar("stripe_payment_intent_id").unique(),
  stripeInvoiceId: varchar("stripe_invoice_id"),
  type: paymentTypeEnum("type").notNull(),
  status: paymentStatusEnum("status").notNull(),
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("USD"),
  description: text("description"),
  metadata: jsonb("metadata"), // Additional payment data
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Financial audit log for compliance
export const auditLogs = pgTable("audit_logs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id),
  entityType: varchar("entity_type").notNull(), // 'payment', 'subscription', 'user', etc.
  entityId: varchar("entity_id").notNull(),
  action: varchar("action").notNull(), // 'create', 'update', 'delete', 'cancel', etc.
  oldValues: jsonb("old_values"), // Previous state
  newValues: jsonb("new_values"), // New state
  metadata: jsonb("metadata"), // Additional context
  ipAddress: varchar("ip_address"),
  userAgent: text("user_agent"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Usage tracking for subscription limits
export const usageMetrics = pgTable("usage_metrics", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  subscriptionId: varchar("subscription_id").references(() => userSubscriptions.id),
  metricType: varchar("metric_type").notNull(), // 'assessment', 'treatment_plan', 'ai_analysis'
  count: integer("count").default(1),
  period: varchar("period").notNull(), // 'daily', 'monthly', 'yearly'
  periodStart: timestamp("period_start").notNull(),
  periodEnd: timestamp("period_end").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Relations
export const usersRelations = relations(users, ({ many, one }) => ({
  assessments: many(assessments),
  treatmentPlans: many(treatmentPlans),
  progressEntries: many(progressEntries),
  crisisAlerts: many(crisisAlerts),
  subscriptions: many(userSubscriptions),
  payments: many(payments),
  usageMetrics: many(usageMetrics),
  auditLogs: many(auditLogs),
}));

export const assessmentsRelations = relations(assessments, ({ one, many }) => ({
  user: one(users, {
    fields: [assessments.userId],
    references: [users.id],
  }),
  treatmentPlans: many(treatmentPlans),
  crisisAlerts: many(crisisAlerts),
}));

export const treatmentPlansRelations = relations(treatmentPlans, ({ one, many }) => ({
  user: one(users, {
    fields: [treatmentPlans.userId],
    references: [users.id],
  }),
  assessment: one(assessments, {
    fields: [treatmentPlans.assessmentId],
    references: [assessments.id],
  }),
  modules: many(treatmentModules),
  progressEntries: many(progressEntries),
}));

export const treatmentModulesRelations = relations(treatmentModules, ({ one, many }) => ({
  plan: one(treatmentPlans, {
    fields: [treatmentModules.planId],
    references: [treatmentPlans.id],
  }),
  progressEntries: many(progressEntries),
}));

export const progressEntriesRelations = relations(progressEntries, ({ one }) => ({
  user: one(users, {
    fields: [progressEntries.userId],
    references: [users.id],
  }),
  plan: one(treatmentPlans, {
    fields: [progressEntries.planId],
    references: [treatmentPlans.id],
  }),
  module: one(treatmentModules, {
    fields: [progressEntries.moduleId],
    references: [treatmentModules.id],
  }),
}));

export const crisisAlertsRelations = relations(crisisAlerts, ({ one }) => ({
  user: one(users, {
    fields: [crisisAlerts.userId],
    references: [users.id],
  }),
  assessment: one(assessments, {
    fields: [crisisAlerts.assessmentId],
    references: [assessments.id],
  }),
  resolvedByUser: one(users, {
    fields: [crisisAlerts.resolvedBy],
    references: [users.id],
  }),
}));

// Subscription relations
export const subscriptionPlansRelations = relations(subscriptionPlans, ({ many }) => ({
  userSubscriptions: many(userSubscriptions),
  payments: many(payments),
}));

export const userSubscriptionsRelations = relations(userSubscriptions, ({ one, many }) => ({
  user: one(users, {
    fields: [userSubscriptions.userId],
    references: [users.id],
  }),
  plan: one(subscriptionPlans, {
    fields: [userSubscriptions.planId],
    references: [subscriptionPlans.id],
  }),
  payments: many(payments),
  usageMetrics: many(usageMetrics),
}));

export const paymentsRelations = relations(payments, ({ one }) => ({
  user: one(users, {
    fields: [payments.userId],
    references: [users.id],
  }),
  subscription: one(userSubscriptions, {
    fields: [payments.subscriptionId],
    references: [userSubscriptions.id],
  }),
  plan: one(subscriptionPlans, {
    fields: [payments.planId],
    references: [subscriptionPlans.id],
  }),
}));

export const auditLogsRelations = relations(auditLogs, ({ one }) => ({
  user: one(users, {
    fields: [auditLogs.userId],
    references: [users.id],
  }),
}));

export const usageMetricsRelations = relations(usageMetrics, ({ one }) => ({
  user: one(users, {
    fields: [usageMetrics.userId],
    references: [users.id],
  }),
  subscription: one(userSubscriptions, {
    fields: [usageMetrics.subscriptionId],
    references: [userSubscriptions.id],
  }),
}));

// Insert schemas
export const insertUserSchema = createInsertSchema(users).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertAssessmentSchema = createInsertSchema(assessments).omit({
  id: true,
  createdAt: true,
});

export const insertTreatmentPlanSchema = createInsertSchema(treatmentPlans).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertTreatmentModuleSchema = createInsertSchema(treatmentModules).omit({
  id: true,
  createdAt: true,
});

export const insertProgressEntrySchema = createInsertSchema(progressEntries).omit({
  id: true,
  createdAt: true,
});

export const insertCrisisAlertSchema = createInsertSchema(crisisAlerts).omit({
  id: true,
  createdAt: true,
});

export const insertConversationAssessmentSchema = createInsertSchema(conversationAssessments).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Subscription insert schemas
export const insertSubscriptionPlanSchema = createInsertSchema(subscriptionPlans).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertUserSubscriptionSchema = createInsertSchema(userSubscriptions).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertPaymentSchema = createInsertSchema(payments).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertAuditLogSchema = createInsertSchema(auditLogs).omit({
  id: true,
  createdAt: true,
});

export const insertUsageMetricSchema = createInsertSchema(usageMetrics).omit({
  id: true,
  createdAt: true,
});

// Auth provider insert schemas
export const insertUserAuthProviderSchema = createInsertSchema(userAuthProviders).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Types
export type UpsertUser = typeof users.$inferInsert;
export type User = typeof users.$inferSelect;

// Support tickets table
export const supportTickets = pgTable("support_tickets", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id).notNull(),
  subject: varchar("subject").notNull(),
  category: varchar("category").notNull(),
  priority: varchar("priority").notNull(),
  description: text("description").notNull(),
  status: varchar("status").default("open"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

export type SupportTicket = typeof supportTickets.$inferSelect;
export type InsertSupportTicket = typeof supportTickets.$inferInsert;
export type InsertUserAuthProvider = z.infer<typeof insertUserAuthProviderSchema>;
export type UserAuthProvider = typeof userAuthProviders.$inferSelect;

export type InsertConversationAssessment = z.infer<typeof insertConversationAssessmentSchema>;
export type ConversationAssessment = typeof conversationAssessments.$inferSelect;
export type InsertAssessment = z.infer<typeof insertAssessmentSchema>;
export type Assessment = typeof assessments.$inferSelect;
export type InsertTreatmentPlan = z.infer<typeof insertTreatmentPlanSchema>;
export type TreatmentPlan = typeof treatmentPlans.$inferSelect;
export type InsertTreatmentModule = z.infer<typeof insertTreatmentModuleSchema>;
export type TreatmentModule = typeof treatmentModules.$inferSelect;
export type InsertProgressEntry = z.infer<typeof insertProgressEntrySchema>;
export type ProgressEntry = typeof progressEntries.$inferSelect;
export type InsertCrisisAlert = z.infer<typeof insertCrisisAlertSchema>;
export type CrisisAlert = typeof crisisAlerts.$inferSelect;

// Subscription types
export type InsertSubscriptionPlan = z.infer<typeof insertSubscriptionPlanSchema>;
export type SubscriptionPlan = typeof subscriptionPlans.$inferSelect;
export type InsertUserSubscription = z.infer<typeof insertUserSubscriptionSchema>;
export type UserSubscription = typeof userSubscriptions.$inferSelect;
