import { useState } from "react";
import { useEffect } from "react";
import { Link } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import Header from "@/components/layout/header";
import PHQ9Form from "@/components/assessment/phq9-form";
import GAD7Form from "@/components/assessment/gad7-form";
import StressBurnoutForm from "@/components/assessment/stress-burnout-form";
import AssessmentResults from "@/components/assessment/assessment-results";
import { Brain, ArrowLeft, Clock } from "lucide-react";

type AssessmentType = 'select' | 'phq9' | 'gad7' | 'stress_burnout' | 'ptsd' | 'sleep_quality' | 'comprehensive';

export default function Assessment() {
  const { toast } = useToast();
  const { isAuthenticated, isLoading } = useAuth();
  const [currentAssessment, setCurrentAssessment] = useState<AssessmentType>('select');
  const [completedAssessment, setCompletedAssessment] = useState<any>(null);

  // Redirect to home if not authenticated
  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      toast({
        title: "Unauthorized",
        description: "You are logged out. Logging in again...",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/api/login";
      }, 500);
      return;
    }
  }, [isAuthenticated, isLoading, toast]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  const assessmentTypes = [
    {
      type: 'phq9' as AssessmentType,
      title: 'PHQ-9 Depression Scale',
      description: 'Validated 9-question assessment to screen for depression severity and track treatment progress.',
      duration: '5-10 minutes',
      color: 'bg-primary/10',
      icon: <Brain className="h-6 w-6 text-primary" />,
      available: true
    },
    {
      type: 'gad7' as AssessmentType,
      title: 'GAD-7 Anxiety Scale',
      description: '7-question screening tool for generalized anxiety disorder with proven reliability and validity.',
      duration: '3-7 minutes',
      color: 'bg-secondary/10',
      icon: <Brain className="h-6 w-6 text-secondary" />,
      available: true
    },
    {
      type: 'stress_burnout' as AssessmentType,
      title: 'Stress & Burnout Scale',
      description: 'Comprehensive assessment of stress levels, burnout symptoms, and coping mechanisms.',
      duration: '8-12 minutes',
      color: 'bg-accent/10',
      icon: <Brain className="h-6 w-6 text-accent" />,
      available: true
    },
    {
      type: 'ptsd' as AssessmentType,
      title: 'PTSD Checklist',
      description: 'Evidence-based screening for post-traumatic stress disorder symptoms and severity.',
      duration: '10-15 minutes',
      color: 'bg-yellow-100',
      icon: <Brain className="h-6 w-6 text-yellow-600" />,
      available: false
    },
    {
      type: 'sleep_quality' as AssessmentType,
      title: 'Sleep Quality Index',
      description: 'Detailed evaluation of sleep patterns, quality, and their impact on mental health.',
      duration: '6-10 minutes',
      color: 'bg-pink-100',
      icon: <Brain className="h-6 w-6 text-pink-600" />,
      available: false
    },
    {
      type: 'comprehensive' as AssessmentType,
      title: 'Complete Assessment',
      description: 'Comprehensive evaluation combining all screening tools for a complete mental health profile.',
      duration: '25-35 minutes',
      color: 'bg-gradient-to-br from-primary/5 to-accent/5',
      icon: <Brain className="h-6 w-6 text-primary" />,
      available: false
    }
  ];

  const handleAssessmentComplete = (result: any) => {
    setCompletedAssessment(result);
    setCurrentAssessment('select');
  };

  const handleBackToSelection = () => {
    setCurrentAssessment('select');
  };

  const handleAssessmentClick = (assessmentType: AssessmentType, available: boolean) => {
    if (!available) {
      toast({
        title: "Coming Soon",
        description: "This assessment is currently under development. We're working to bring you more validated screening tools soon!",
        variant: "default",
      });
      return;
    }
    setCurrentAssessment(assessmentType);
  };

  if (completedAssessment) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <main className="container mx-auto px-4 py-8">
          <AssessmentResults 
            assessment={completedAssessment}
            onStartNew={() => {
              setCompletedAssessment(null);
              setCurrentAssessment('select');
            }}
          />
        </main>
      </div>
    );
  }

  if (currentAssessment === 'phq9') {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <main className="container mx-auto px-4 py-8">
          <div className="mb-6">
            <Button 
              variant="ghost" 
              onClick={handleBackToSelection}
              className="mb-4"
              data-testid="button-back-to-selection"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Assessment Selection
            </Button>
          </div>
          <PHQ9Form onComplete={handleAssessmentComplete} />
        </main>
      </div>
    );
  }

  if (currentAssessment === 'gad7') {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <main className="container mx-auto px-4 py-8">
          <div className="mb-6">
            <Button 
              variant="ghost" 
              onClick={handleBackToSelection}
              className="mb-4"
              data-testid="button-back-to-selection"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Assessment Selection
            </Button>
          </div>
          <GAD7Form onComplete={handleAssessmentComplete} />
        </main>
      </div>
    );
  }

  if (currentAssessment === 'stress_burnout') {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <main className="container mx-auto px-4 py-8">
          <div className="mb-6">
            <Button 
              variant="ghost" 
              onClick={handleBackToSelection}
              className="mb-4"
              data-testid="button-back-to-selection"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Assessment Selection
            </Button>
          </div>
          <StressBurnoutForm onComplete={handleAssessmentComplete} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background" data-testid="assessment-page">
      <Header />

      <main className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <Link href="/">
            <Button variant="ghost" className="mb-4" data-testid="button-back-home">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Home
            </Button>
          </Link>
          <h1 className="text-3xl font-bold text-foreground mb-2" data-testid="text-assessment-title">
            Mental Health Assessment
          </h1>
          <p className="text-muted-foreground">
            Choose from our clinically validated screening tools to get personalized insights into your mental health.
          </p>
        </div>

        {/* Assessment Selection */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {assessmentTypes.map((assessment) => (
            <Card 
              key={assessment.type}
              className={`transition-shadow ${assessment.available ? 'hover:shadow-lg cursor-pointer' : 'opacity-75'} group`}
              onClick={() => handleAssessmentClick(assessment.type, assessment.available)}
              data-testid={`card-assessment-${assessment.type}`}
            >
              <CardHeader>
                <div className={`w-12 h-12 ${assessment.color} rounded-lg flex items-center justify-center mb-4`}>
                  {assessment.icon}
                </div>
                <CardTitle className="text-xl">{assessment.title}</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-muted-foreground mb-4">{assessment.description}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2 text-sm text-muted-foreground">
                    <Clock className="h-4 w-4" />
                    <span>{assessment.duration}</span>
                  </div>
                  {assessment.type === 'comprehensive' && assessment.available && (
                    <Badge className="bg-primary text-primary-foreground">
                      Recommended
                    </Badge>
                  )}
                  {!assessment.available && (
                    <Badge variant="secondary">
                      Coming Soon
                    </Badge>
                  )}
                </div>
                <Button 
                  className={`w-full mt-4 transition-colors ${assessment.available ? 'group-hover:bg-primary/90' : 'opacity-60 cursor-not-allowed'}`}
                  data-testid={`button-start-${assessment.type}`}
                  disabled={!assessment.available}
                >
                  {assessment.available ? 'Start Assessment' : 'Coming Soon'}
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Information Cards */}
        <div className="grid md:grid-cols-2 gap-6 mt-12">
          <Card data-testid="card-what-to-expect">
            <CardHeader>
              <CardTitle>What to Expect</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-start space-x-3">
                <div className="w-6 h-6 bg-primary/10 rounded-full flex items-center justify-center mt-0.5">
                  <span className="text-xs font-semibold text-primary">1</span>
                </div>
                <div>
                  <h4 className="font-semibold">Complete Assessment</h4>
                  <p className="text-sm text-muted-foreground">Answer questions honestly about your recent experiences and feelings.</p>
                </div>
              </div>
              <div className="flex items-start space-x-3">
                <div className="w-6 h-6 bg-primary/10 rounded-full flex items-center justify-center mt-0.5">
                  <span className="text-xs font-semibold text-primary">2</span>
                </div>
                <div>
                  <h4 className="font-semibold">AI Analysis</h4>
                  <p className="text-sm text-muted-foreground">Our AI analyzes your responses using clinical guidelines and research.</p>
                </div>
              </div>
              <div className="flex items-start space-x-3">
                <div className="w-6 h-6 bg-primary/10 rounded-full flex items-center justify-center mt-0.5">
                  <span className="text-xs font-semibold text-primary">3</span>
                </div>
                <div>
                  <h4 className="font-semibold">Personalized Results</h4>
                  <p className="text-sm text-muted-foreground">Receive detailed insights and recommendations for your mental health.</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card data-testid="card-privacy-security">
            <CardHeader>
              <CardTitle>Privacy & Security</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center space-x-3">
                <Badge variant="secondary" className="flex items-center gap-2">
                  <Brain className="h-4 w-4" />
                  HIPAA Compliant
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground">
                Your mental health information is protected with enterprise-grade encryption and security measures. 
                All data is stored securely and never shared without your explicit consent.
              </p>
              <div className="space-y-2 text-sm">
                <div className="flex items-center space-x-2">
                  <div className="w-2 h-2 bg-secondary rounded-full"></div>
                  <span>End-to-end encryption</span>
                </div>
                <div className="flex items-center space-x-2">
                  <div className="w-2 h-2 bg-secondary rounded-full"></div>
                  <span>Secure data storage</span>
                </div>
                <div className="flex items-center space-x-2">
                  <div className="w-2 h-2 bg-secondary rounded-full"></div>
                  <span>No data sharing without consent</span>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Important Notice */}
        <Card className="mt-8 border-yellow-200 bg-yellow-50" data-testid="card-disclaimer">
          <CardContent className="p-6">
            <div className="flex items-start space-x-3">
              <div className="w-6 h-6 bg-yellow-500 rounded-full flex items-center justify-center mt-0.5">
                <span className="text-xs font-bold text-white">!</span>
              </div>
              <div>
                <h4 className="font-semibold text-yellow-800 mb-2">Important Notice</h4>
                <p className="text-sm text-yellow-700 leading-relaxed">
                  This assessment is for informational purposes only and is not a substitute for professional medical advice, 
                  diagnosis, or treatment. If you are experiencing a mental health emergency, please contact 911 or your local 
                  emergency services immediately. For crisis support, call the National Suicide Prevention Lifeline at 988.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      </main>
    </div>
  );
}

