import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import pureSoulLogo from "@assets/puresoul-1image_1763172242251.jpg";

interface Slide {
  title: string;
  highlight?: string;
  description: string;
  buttonText: string;
  buttonAction: () => void;
  backgroundType: "gradient" | "image";
  backgroundImage?: string;
  titleColor?: string;
}

export default function HeroSlider() {
  const [currentSlide, setCurrentSlide] = useState(0);

  const slides: Slide[] = [
    {
      title: "Discover Your Inner World",
      highlight: "With AI",
      description: "AI-powered self-reflection and personalized growth journeys.",
      buttonText: "Start Your Journey",
      buttonAction: () => window.location.href = "/auth",
      backgroundType: "gradient",
    },
    {
      title: "Know Yourself Better",
      description: "Explore your thoughts, emotions, and personality with AI insights.",
      buttonText: "Learn More",
      buttonAction: () => document.getElementById("section-how-it-works")?.scrollIntoView({ behavior: "smooth" }),
      backgroundType: "gradient",
      titleColor: "from-primary to-accent",
    },
    {
      title: "Personal Growth Made Simple",
      description: "AI-powered conversations designed for self-discovery.",
      buttonText: "Explore Features",
      buttonAction: () => document.getElementById("section-assessments")?.scrollIntoView({ behavior: "smooth" }),
      backgroundType: "gradient",
      titleColor: "from-secondary to-accent",
    },
    {
      title: "Unlock Your Potential",
      description: "Build self-awareness and grow at your own pace.",
      buttonText: "Get Started Free",
      buttonAction: () => window.location.href = "/auth",
      backgroundType: "gradient",
      titleColor: "from-accent to-primary",
    }
  ];

  const slideCount = slides.length;

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slideCount);
    }, 5000);

    return () => clearInterval(interval);
  }, [slideCount]);

  const goToSlide = (index: number) => {
    setCurrentSlide(index);
  };

  const currentSlideData = slides[currentSlide];

  return (
    <div className="relative overflow-hidden bg-gradient-to-br from-primary/5 via-accent/5 to-secondary/5">
      {/* Logo Hologram Background */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <img
          src={pureSoulLogo}
          alt=""
          className="w-64 h-64 lg:w-80 lg:h-80 object-contain opacity-[0.08] blur-[1px]"
          aria-hidden="true"
        />
      </div>

      <div className="container mx-auto px-4 py-10 lg:py-12 relative z-10">
        <div className="relative min-h-[300px] lg:min-h-[320px] flex items-center justify-center">
          {/* Slides Container */}
          <div className="w-full max-w-2xl mx-auto">
            {slides.map((slide, index) => (
              <div
                key={index}
                className={`transition-all duration-700 ease-in-out ${
                  index === currentSlide
                    ? "opacity-100 translate-x-0 relative z-10 pointer-events-auto"
                    : index < currentSlide
                    ? "opacity-0 -translate-x-full absolute inset-0 z-0 pointer-events-none"
                    : "opacity-0 translate-x-full absolute inset-0 z-0 pointer-events-none"
                }`}
              >
                <div className="flex flex-col items-center justify-center text-center space-y-4 px-4">
                  <h1 className="text-3xl lg:text-4xl xl:text-5xl font-bold text-foreground leading-tight max-w-xl">
                    {slide.highlight ? (
                      <>
                        {slide.title}
                        <span className={`block ${slide.titleColor || "bg-gradient-to-r from-primary to-accent"} bg-clip-text text-transparent`}>
                          {slide.highlight}
                        </span>
                      </>
                    ) : (
                      <span className={slide.titleColor ? `bg-gradient-to-r ${slide.titleColor} bg-clip-text text-transparent` : ""}>
                        {slide.title}
                      </span>
                    )}
                  </h1>

                  <p className="text-base lg:text-lg text-muted-foreground leading-relaxed max-w-lg">
                    {slide.description}
                  </p>

                  <div className="flex justify-center pt-2">
                    <Button
                      size="lg"
                      onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        slide.buttonAction();
                      }}
                      className="bg-gradient-to-r from-primary to-accent text-white px-7 py-4 text-base font-semibold shadow-lg hover:shadow-xl transition-all cursor-pointer"
                      data-testid={`button-slide-${index}`}
                    >
                      {slide.buttonText}
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Navigation Dots */}
        <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex gap-2 z-10">
          {slides.map((_, index) => (
            <button
              key={index}
              onClick={() => goToSlide(index)}
              className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
                index === currentSlide
                  ? "bg-primary scale-125"
                  : "bg-muted-foreground/30 hover:bg-muted-foreground/50"
              }`}
              aria-label={`Go to slide ${index + 1}`}
              data-testid={`dot-${index}`}
            />
          ))}
        </div>
      </div>

      {/* Floating Animation CSS */}
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-20px); }
        }
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
}

remove-admin.ts.content:
import { db } from "./server/db";
import { users } from "./shared/schema";
import { eq } from "drizzle-orm";

async function removeAdminUser() {
  try {
    console.log("Removing admin privileges from admin.test@example.com...");

    const result = await db
      .update(users)
      .set({ isAdmin: false })
      .where(eq(users.email, "admin.test@example.com"))
      .returning({ 
        id: users.id, 
        email: users.email, 
        isAdmin: users.isAdmin 
      });

    if (result.length === 0) {
      console.log("❌ User not found: admin.test@example.com");
    } else {
      console.log("✅ Admin privileges removed successfully!");
      console.log("User:", result[0].email);
      console.log("Is Admin:", result[0].isAdmin);
    }

    process.exit(0);
  } catch (error) {
    console.error("❌ Error removing admin privileges:", error);
    process.exit(1);
  }
}

removeAdminUser();

client/src/components/age-gate.tsx.content:
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { AlertTriangle } from "lucide-react";

interface AgeGateProps {
  onConfirm: () => void;
}

export function AgeGate({ onConfirm }: AgeGateProps) {
  const [showWarning, setShowWarning] = useState(false);

  const handleConfirm = () => {
    localStorage.setItem("age_verified", "true");
    onConfirm();
  };

  const handleDecline = () => {
    setShowWarning(true);
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
      <Card className="w-full max-w-md border-2 border-primary/20">
        <CardHeader className="text-center space-y-4">
          <div className="flex justify-center">
            <div className="bg-amber-500/10 p-4 rounded-full">
              <AlertTriangle className="h-12 w-12 text-amber-500" />
            </div>
          </div>
          <CardTitle className="text-2xl">Age Verification Required</CardTitle>
          <CardDescription className="text-base">
            You must be 18 years or older to access this website
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="bg-muted p-4 rounded-lg space-y-2 text-sm">
            <p className="font-semibold">Important Disclaimer:</p>
            <p>
              This website provides AI-powered self-awareness and personal growth content for educational and entertainment purposes only.
            </p>
            <p className="font-semibold text-destructive">
              This is NOT medical advice, therapy, or mental health treatment.
            </p>
            <p>
              If you are experiencing a mental health crisis, please contact a licensed healthcare provider or call emergency services.
            </p>
          </div>

          {showWarning && (
            <div className="bg-destructive/10 border border-destructive/20 p-4 rounded-lg">
              <p className="text-sm text-destructive font-semibold">
                You must be 18+ to access this website. Please exit if you are under 18.
              </p>
            </div>
          )}

          <div className="space-y-3">
            <Button 
              onClick={handleConfirm} 
              className="w-full h-12 text-base"
              data-testid="button-age-confirm"
            >
              I am 18 or older - Enter
            </Button>
            <Button 
              onClick={handleDecline} 
              variant="outline" 
              className="w-full h-12 text-base"
              data-testid="button-age-decline"
            >
              I am under 18 - Exit
            </Button>
          </div>

          <p className="text-xs text-muted-foreground text-center">
            By clicking "I am 18 or older", you confirm that you meet the age requirement and agree to use this service for personal growth and self-awareness purposes only.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

export function useAgeVerification() {
  const [isVerified, setIsVerified] = useState<boolean | null>(null);

  useEffect(() => {
    const verified = localStorage.getItem("age_verified") === "true";
    setIsVerified(verified);
  }, []);

  return {
    isVerified,
    setVerified: () => {
      localStorage.setItem("age_verified", "true");
      setIsVerified(true);
    }
  };
}
